# Let's try a construction using GF(8)
# GF(8) = GF(2)[x]/(x^3 + x + 1)
# Elements: 0, 1, α, α^2, α^3=α+1, α^4=α^2+α, α^5=α^2+α+1, α^6=α^2+1

# Represent elements as integers 0-7 (binary representation of polynomial coefficients)
# 0 = 000, 1 = 001, α = 010, α^2 = 100, α^3 = 011, α^4 = 110, α^5 = 111, α^6 = 101

# Addition in GF(8) is XOR
# Multiplication: use the primitive polynomial x^3 + x + 1

def gf8_add(a, b):
    return a ^ b

def gf8_mul(a, b):
    # Multiply in GF(8) with primitive polynomial x^3 + x + 1
    result = 0
    for i in range(3):
        if (b >> i) & 1:
            result ^= (a << i)
    # Reduce modulo x^3 + x + 1 (which is 0b1011 = 11)
    for i in range(5, 2, -1):
        if (result >> i) & 1:
            result ^= (0b1011 << (i - 3))
    return result & 0b111

# Test multiplication table
print("GF(8) multiplication table:")
for i in range(8):
    row = [gf8_mul(i, j) for j in range(8)]
    print(row)

# Now construct OLS using GF(8):
# X[i][j] = i + j (in GF(8))
# Y[i][j] = a*i + j (in GF(8)) for some a ≠ 0, 1

# For orthogonality, we need a ≠ 0 and a ≠ 1
# Let's try a = α = 2

def check_ols_gf(X, Y, n):
    for i in range(n):
        if len(set(X[i])) != n:
            return False, f"X row {i} not distinct"
        if len(set(Y[i])) != n:
            return False, f"Y row {i} not distinct"
    for j in range(n):
        col_x = [X[i][j] for i in range(n)]
        col_y = [Y[i][j] for i in range(n)]
        if len(set(col_x)) != n:
            return False, f"X col {j} not distinct"
        if len(set(col_y)) != n:
            return False, f"Y col {j} not distinct"
    pairs = set()
    for i in range(n):
        for j in range(n):
            p = (X[i][j], Y[i][j])
            if p in pairs:
                return False, f"Duplicate pair {p}"
            pairs.add(p)
    return True, "OK"

n = 8
for a in range(2, 8):
    X = [[gf8_add(i, j) for j in range(n)] for i in range(n)]
    Y = [[gf8_add(gf8_mul(a, i), j) for j in range(n)] for i in range(n)]
    ok, msg = check_ols_gf(X, Y, n)
    if ok:
        print(f"\nFound with a={a}")
        print("X:")
        for row in X:
            print(row)
        print("Y:")
        for row in Y:
            print(row)
        result_list = [val for row in X for val in row] + [val for row in Y for val in row]
        print(f"\nResult: {result_list}")
        break
    else:
        print(f"a={a}: {msg}")
